import csv, json, re
from collections import defaultdict
from decimal import Decimal

def cents(s):
    return int(round(Decimal(s) * 100))

invoices = {}
with open("backoffice/invoices.csv", newline="", encoding="utf-8") as f:
    for row in csv.DictReader(f):
        invoices[row["id"]] = cents(row["amount"])

payments = defaultdict(list)
ignored = []
with open("backoffice/bank_statement_june.csv", newline="", encoding="utf-8") as f:
    for row in csv.DictReader(f):
        memo = row["memo"]
        amt = cents(row["amount"])
        nums = re.findall(r"\d{3,}", memo)
        if amt <= 0:
            ignored.append((memo, row["amount"], "fee/interest/debit"))
            continue
        ids = [f"INV-{n}" for n in nums if f"INV-{n}" in invoices]
        if not ids:
            ignored.append((memo, row["amount"], "no identifiable invoice"))
            continue
        payments[ids[0]].append({"date": row["date"], "memo": memo, "amount": amt})

unpaid, duplicated, mismatched = [], [], []
for inv_id, amount in invoices.items():
    pays = payments.get(inv_id, [])
    if not pays:
        unpaid.append(inv_id)
    elif len(pays) > 1:
        duplicated.append(inv_id)
    elif pays[0]["amount"] != amount:
        mismatched.append({
            "id": inv_id,
            "invoiced": float(amount / 100),
            "paid": float(pays[0]["amount"] / 100),
        })

result = {
    "unpaid": unpaid,
    "duplicated": duplicated,
    "mismatched": mismatched,
}
with open("result.json", "w", encoding="utf-8") as f:
    json.dump(result, f, indent=2, ensure_ascii=False)
    f.write("\n")

print("invoices:", len(invoices), "paid ids:", len(payments),
      "unpaid:", len(unpaid), "duplicated:", len(duplicated),
      "mismatched:", len(mismatched))
print("ignored:", ignored)
print(json.dumps(result, indent=2, ensure_ascii=False))

